use std::io::{self, Write};
use std::process;

pub fn parse_count_from_env() -> i32 {
    parse_count_from_args(std::env::args())
}

pub fn parse_count_from_args<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let mut args = args.into_iter();
    let _program = args.next();

    match args.next() {
        Some(flag) if flag == "--a" => {
            let raw = match args.next() {
                Some(arg) => arg,
                None => abort_with(
                    "std::logic_error",
                    "basic_string::_S_construct null not valid",
                ),
            };

            match stoi_like_i32(&raw) {
                Ok(value) => value,
                Err(StoiError::InvalidArgument) => abort_with("std::invalid_argument", "stoi"),
                Err(StoiError::OutOfRange) => abort_with("std::out_of_range", "stoi"),
            }
        }
        _ => 18,
    }
}

enum StoiError {
    InvalidArgument,
    OutOfRange,
}

fn stoi_like_i32(input: &str) -> Result<i32, StoiError> {
    let bytes = input.as_bytes();
    let mut index = 0;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let negative = match bytes.get(index) {
        Some(b'+') => {
            index += 1;
            false
        }
        Some(b'-') => {
            index += 1;
            true
        }
        _ => false,
    };

    let digits_start = index;
    let mut magnitude = 0_i64;

    while let Some(byte) = bytes.get(index) {
        if !byte.is_ascii_digit() {
            break;
        }

        magnitude = magnitude
            .checked_mul(10)
            .and_then(|value| value.checked_add(i64::from(byte - b'0')))
            .ok_or(StoiError::OutOfRange)?;

        if !negative && magnitude > i64::from(i32::MAX) {
            return Err(StoiError::OutOfRange);
        }

        if negative && -magnitude < i64::from(i32::MIN) {
            return Err(StoiError::OutOfRange);
        }

        index += 1;
    }

    if index == digits_start {
        return Err(StoiError::InvalidArgument);
    }

    if negative {
        Ok(-(magnitude as i32))
    } else {
        Ok(magnitude as i32)
    }
}

fn abort_with(exception: &str, what: &str) -> ! {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of '{}'",
        exception
    );
    let _ = writeln!(stderr, "  what():  {}", what);
    let _ = stderr.flush();
    process::abort();
}

