mod tests {
    use super::cli::parse_count_from_args;
    use super::hopscotch::HopscotchMap;

    #[test]
    fn reserves_match_observed_thresholds() {
        for (count, buckets) in [
            (-1, 0),
            (0, 0),
            (1, 2),
            (2, 4),
            (14, 16),
            (15, 32),
            (28, 32),
            (29, 64),
            (57, 64),
            (58, 128),
            (921, 1024),
            (922, 2048),
        ] {
            let mut map = HopscotchMap::<i32, i32>::new();
            map.reserve(count);
            assert_eq!(map.bucket_count(), buckets);
        }
    }

    #[test]
    fn parses_like_the_cxx_entrypoint() {
        assert_eq!(parse_count_from_args(["prog".to_string()]), 18);
        assert_eq!(
            parse_count_from_args(["prog".to_string(), "--a".to_string(), "5x".to_string()]),
            5
        );
        assert_eq!(
            parse_count_from_args(["prog".to_string(), "--a".to_string(), " 5".to_string()]),
            5
        );
        assert_eq!(
            parse_count_from_args(["prog".to_string(), "ignored".to_string(), "7".to_string()]),
            18
        );
    }
}
